KINDS = ["identity","classification","relationship","authority","requirement","constraint","event","temporal","composition","evidence","ownership","measurement","exception","provenance","process","validation","privacy","lifecycle","quality","security","retention","interoperability","decision","state"]

def make_finding(item, n, refs):
    fid, name, primary, required = item
    low = name.lower()
    kinds = [primary, KINDS[(n+7) % len(KINDS)], KINDS[(n+15) % len(KINDS)]]
    return {"id": fid, "name": name,
      "description": f"Records {low} as versioned benchmark-definition context while evaluation runs, models, results, leaderboards, policies and records masters remain external.",
      "source_refs": refs,
      "questions": [
        {"id": f"{fid}-q01", "text": f"What stable identity, benchmark release, declared value and explicit unknown establish {low}?", "kind": kinds[0], "answer_data": ["benchmark and release identifiers", "typed value and applicable scope", "unknown, withheld and not-applicable states"]},
        {"id": f"{fid}-q02", "text": f"Who may create, assert, review, approve, correct or disclose {low}, under which purpose and authority?", "kind": kinds[1], "answer_data": ["owner, steward, contributor and reviewer", "purpose, authority, policy and access", "exception, contest and escalation path"]},
        {"id": f"{fid}-q03", "text": f"Which effective, observed, recorded, ingested and knowledge times, evidence and uncertainty qualify {low}?", "kind": kinds[2], "answer_data": ["distinct event and knowledge times", "source, method, evidence and uncertainty", "successor, correction, retention and audit"]}],
      "data_elements": [{"id": f"{fid}-data", "name": f"{name} data", "description": f"Typed benchmark data for {low}, qualified by release, scope, source, authority, time, evidence and provenance.", "value_kind": "collection", "cardinality": "1" if required else "0..n", "required": required, "source_refs": refs}],
      "artifacts": [{"id": f"{fid}-record", "name": f"{name} record", "description": f"Immutable or successor-versioned evidence for {low}.", "media_or_form": ["logical benchmark assertion", "dataset, protocol, metric, validation, lifecycle or projection record"], "serial": True, "identity_strategy": f"Benchmark release ID plus independent assertion, item, decision or artifact ID for {fid}; name, split label, URL, digest and timestamp never identify it alone.", "source_refs": refs}],
      "inline_only_rationale": None}

def structure():
    bundles, n = [], 0
    for bid, bname, rationale, layers in ROWS:
        rendered = []
        for lid, lname, refs, items in layers:
            fs = []
            for item in items:
                n += 1; fs.append(make_finding(item, n, refs))
            rendered.append({"id": lid, "name": lname, "description": f"Groups benchmark context for {lname.lower()}.", "source_refs": refs, "findings": fs})
        bundles.append({"id": bid, "name": bname, "description": f"Groups governed context for {bname.lower()}.", "rationale": rationale + ".", "source_refs": sorted({r for layer in layers for r in layer[2]}), "layers": rendered})
    return {"bundles": bundles}

